/**
 * Photos in a grid, a masonry of mixed heights, or a featured picture over thumbnails, with a dialog that shows
 * the selected photo. Static markup: the dialog open state is a prop. Axes: layout (grid, masonry, featured),
 * captions (show, hide), lightbox (open, closed).
 */
import { type ReactNode } from "react";
import { Box, Button, Group, Stack, Text } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { FigureBlock } from "../components/figure-block";
import { LightboxStage } from "../components/lightbox-stage";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl } from "../utils";
import type { LightboxLabels } from "./lightbox-gallery.types";
import type { Photo } from "./photo-gallery.types";

export type LightboxGalleryProps = {
  id: string;
  title: string;
  lead?: string;
  photos: Photo[];
  empty?: string;
  labels: LightboxLabels;
  layout?: "grid" | "masonry" | "featured";
  captions?: "show" | "hide";
  lightbox?: "open" | "closed";
  landmarkLabel?: string;
};

export function LightboxGallery({
  id,
  title,
  lead = "",
  photos,
  empty = "",
  labels,
  layout = "grid",
  captions = "show",
  lightbox = "closed",
  landmarkLabel,
}: LightboxGalleryProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} landmarkLabel={landmarkLabel}>
      {((photos?.length ?? 0) === 0) ? (
        <EmptyState icon="image" title={empty} />
      ) : (
        <>
          {((layout as string) === "featured") ? (
            <Stack gap="4" align="stretch" data-slot="featured">
              <MediaFrame alt={title} />
              <Group gap="4" align="center" justify="between">
                <Stack gap="0">
                  <Text size="base" weight="semibold">
                    {photos[0]?.title ?? ""}
                  </Text>
                  <Text size="xs" className="text-muted-foreground">
                    {tpl(labels.counter, 1, (photos?.length ?? 0))}
                  </Text>
                </Stack>
                <Group gap="2">
                  <Button variant="outline" size="sm" layout="icon" type="button" aria-label={labels.previous}>
                    <LucideIcon name="chevron-left" size={16} />
                  </Button>
                  <Button variant="outline" size="sm" layout="icon" type="button" aria-label={labels.next}>
                    <LucideIcon name="chevron-right" size={16} />
                  </Button>
                </Group>
              </Group>
              <Box className="grid grid-cols-3 gap-2 sm:grid-cols-9" data-slot="thumbs">
                {(photos ?? []).map((p, i) => (
                  <MediaFrame key={p.id} alt={p.title} ratio="1/1" className={((i === 0) ? "ring-2 ring-foreground" : "")} />
                ))}
              </Box>
            </Stack>
          ) : (
            <Box
              className={
                (layout as string) === "masonry" ? "columns-1 gap-4 sm:columns-2 lg:columns-3"
                : "grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3"
              }
              data-slot="items"
            >
              {(photos ?? []).map((p, i) => (
                <FigureBlock key={p.id}
                  className={cn(
                    "relative flex flex-col gap-2",
                    (((layout as string) === "masonry") ? "mb-4 break-inside-avoid" : "")
                  )}
                  testid="item"
                >
                  <MediaFrame
                    alt={p.title}
                    ratio={
                      (layout as string) === "masonry" ? ((p.size === "tall") ? "3/4" : ((p.size === "wide") ? "16/9" : ((p.size === "large") ? "4/3" : "1/1")))
                      : "4/3"
                    }
                  />
                  <Button
                    variant="ghost"
                    size="sm"
                    layout="icon"
                    type="button"
                    className="absolute right-2 top-2 bg-background"
                    aria-label={labels.open}
                  >
                    <LucideIcon name="arrow-up-right" size={16} />
                  </Button>
                  {(((captions as string) === "show") && (((layout as string) === "grid") || ((layout as string) === "masonry"))) ? (
                    <Box className="text-sm text-muted-foreground" data-slot="caption">
                      {p.title}
                    </Box>
                  ) : null}
                </FigureBlock>
              ))}
            </Box>
          )}
          <LightboxStage photos={photos} labels={labels} captions={captions} lightbox={lightbox} />
        </>
      )}
    </SectionFrame>
  );
}

